"""Generate antialiased glyph coverage for the embedded clock (Pillow)."""

from pathlib import Path

from PIL import Image, ImageDraw, ImageFont

ROOT = Path(__file__).resolve().parents[1]
out = [
    "// Generated by scripts/generate_fonts.py. Barlow fonts: SIL OFL 1.1.",
    "#pragma once",
    "#include <stdint.h>",
    "struct ClockGlyph { uint32_t offset; uint16_t width, height, advance; };",
    "struct ClockFont { const uint8_t *pixels; const ClockGlyph *glyphs; int height; };",
]
for name, path, size in [
    ("large", str(ROOT / "assets/fonts/barlow-semi-condensed/BarlowSemiCondensed-Medium.ttf"), 112),
    ("small", str(ROOT / "assets/fonts/barlow/Barlow-Regular.ttf"), 23),
]:
    font = ImageFont.truetype(path, size)
    top = font.getbbox("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ:.-")[1]
    bottom = font.getbbox("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ:.-")[3]
    height = bottom - top
    pixels, glyphs = [], []
    for code in range(32, 127):
        c = chr(code)
        advance = round(font.getlength(c))
        width = max(advance, font.getbbox(c)[2]) + 1
        im = Image.new("L", (width, height))
        ImageDraw.Draw(im).text((0, -top), c, font=font, fill=255)
        glyphs.append((len(pixels), width, height, advance))
        pixels.extend(im.tobytes())
    out.append(f"const uint8_t {name}Pixels[] = {{")
    out.extend(",".join(map(str, pixels[i : i + 64])) + "," for i in range(0, len(pixels), 64))
    out.append("};")
    out.append(f"const ClockGlyph {name}Glyphs[] = {{")
    out.extend("{" + ",".join(map(str, glyph)) + "}," for glyph in glyphs)
    out.append("};")
    out.append(f"const ClockFont {name}Font = {{{name}Pixels,{name}Glyphs,{height}}};")
(ROOT / "examples/gravity-clock/GravityClock/ClockFonts.h").write_text("\n".join(out) + "\n")
